"""What Workpeg's install refuses in a function bundle, checked before it
leaves the developer's machine.

Workpeg reads a function bundle's ``Dockerfile`` and ``workpeg.json`` before
it builds anything (``check_bundle`` and ``check_dockerfile`` in the api's
``installed_pegs/function_container.py``), and refuses one that could reach
past its own build context. Until this module the SDK read neither, so a
refused bundle uploaded cleanly and the refusal was seen only by an operator
at install, never by the developer who could fix it.

This is a port of those rules, not a call to them: the api is the authority
and keeps its own copy, so nothing a developer changes in their SDK can
loosen the install's check. The two must agree, which is why the messages
are the api's own, word for word, and why ``tests/test_function_check.py``
carries the api's cases. When the api's rules change, change this file and
those tests in the same release.

Fail closed, as the api does: anything this cannot read as Docker does is
refused, not guessed at.
"""
from __future__ import annotations

import itertools
import json
import re
import stat
from pathlib import Path

from workpeg.function_base import IMAGE as PLATFORM_BASE
from workpeg.function_base import RELEASE as _RELEASE

#: The official images a function's FROM may name, written ``<name>`` or
#: ``<name>:<tag>``: python only, and never an ``-onbuild`` tag.
ALLOWED_BASES = ("python",)

#: Docker's rule for a tag (distribution/reference).
_TAG = re.compile(r"[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}")

#: What Workpeg builds: the Dockerfile, and the function itself.
_REQUIRED = ("Dockerfile", "app/main.py")

#: Printable ASCII, tabs and line ends: the only text the check reads
#: exactly as Docker does. A carriage return is a line end only before a
#: newline.
_UNREADABLE = re.compile(r"[^\t\n\r\x20-\x7e]|\r(?!\n)")

#: A parser directive: ``# name=value`` before the first instruction.
_DIRECTIVE = re.compile(r"#[ \t]*[A-Za-z][A-Za-z0-9]*[ \t]*=")

#: A backslash, then spaces or tabs only, at the end of a line: it
#: continues on the next.
_CONTINUES = re.compile(r"\\[ \t]*\Z")

#: Two at the end, which one Docker parser reads as continued and another
#: as ended.
_ESCAPED_END = re.compile(r"\\\\[ \t]*\Z")

#: Docker's rule for a stage's AS name, which it folds to lower case.
_STAGE = re.compile(r"[a-z][a-z0-9_.-]*")

#: Every instruction but ONBUILD, VOLUME and LABEL.
_INSTRUCTIONS = frozenset((
    "add", "arg", "cmd", "copy", "entrypoint", "env", "expose", "from",
    "healthcheck", "maintainer", "run", "shell", "stopsignal", "user",
    "workdir"))


class BundleRefused(RuntimeError):
    """Workpeg's install would refuse this function bundle. The message is
    the one the install gives."""


def check_bundle(directory) -> Path:
    """The project as a resolved Path, once Workpeg would build it: a
    regular ``Dockerfile`` and ``app/main.py``, a Dockerfile
    :func:`check_dockerfile` accepts, and a ``workpeg.json`` that names no
    image. Otherwise :class:`BundleRefused`."""
    project = check_files(directory)
    check_config(project)
    return project


def check_files(directory) -> Path:
    """The Dockerfile and ``app/main.py`` half of :func:`check_bundle`."""
    project = Path(directory).resolve()
    for required in _REQUIRED:
        if not _is_regular(project / required):
            raise BundleRefused(
                f"The function bundle has no regular file {required}.")
    # Bytes, not text mode: text mode would turn a lone carriage return
    # into a line end, which Docker does not.
    try:
        dockerfile = (project / "Dockerfile").read_bytes().decode("utf-8")
    except ValueError:
        raise BundleRefused(
            "The function bundle's Dockerfile cannot be read as UTF-8 text.")
    check_dockerfile(dockerfile)
    return project


def check_config(project) -> None:
    """Refuse a ``workpeg.json`` that is not a JSON object, or that names
    the image (``build.image``): Workpeg names every function image."""
    try:
        config = json.loads(
            (Path(project) / "workpeg.json").read_text(encoding="utf-8"))
    except FileNotFoundError:
        return
    except (OSError, ValueError, RecursionError):
        raise BundleRefused(
            "The function bundle's workpeg.json cannot be read as JSON.")
    if not isinstance(config, dict):
        raise BundleRefused(
            "The function bundle's workpeg.json is not a JSON object.")
    build = config.get("build")
    if build is not None and (not isinstance(build, dict)
                              or build.get("image") is not None):
        raise BundleRefused(
            "The function bundle names its own image (build.image in "
            "workpeg.json). The platform names every function image; "
            "upload a new version without build.image.")


def check_dockerfile(text: str) -> None:
    """Refuse, with :class:`BundleRefused` naming the line, a function
    Dockerfile Workpeg's install would refuse (docs/function-base.md, "The
    rules for every function build")."""
    bad = _UNREADABLE.search(text)
    if bad:
        _refuse(text.count("\n", 0, bad.start()) + 1,
                "is not plain ASCII text with tabs and line ends only, "
                "which is all this check can read exactly as Docker does")
    stages: list[str] = []  # each stage's AS name so far, '' when none
    for number, line in _instructions(text):
        if "<<" in line:
            _refuse(number, "has a heredoc (<<), which Docker reads by "
                    "rules of its own; write the file and COPY it")
        keyword, *words = line.split()
        keyword = keyword.lower()
        flags = list(itertools.takewhile(lambda w: w.startswith("--"), words))
        args = words[len(flags):]
        if keyword not in _INSTRUCTIONS:
            _refuse(number, "is not an instruction a function Dockerfile "
                    "may use (ONBUILD, VOLUME and LABEL are not)")
        if any(c in flag for flag in flags for c in "\"'\\"):
            _refuse(number, "has a flag with a quote or a backslash in it")
        if keyword == "from":
            stages.append(_from(number, args, stages))
        if keyword == "run" and flags:
            _refuse(number, "is a RUN step with a -- flag (--network, "
                    "--security, --device, --mount): a function RUN step "
                    "takes none")
        for flag in flags if keyword in ("copy", "add") else ():
            name, _, value = flag[2:].partition("=")
            # Docker folds a stage name to lower case where AS defines it
            # and where --from looks it up, so --from=Build is the stage
            # 'build'. A stage name is only ever _STAGE once folded, so no
            # image reference, with its ':' or '/', can match one.
            if name.lower() == "from" and value.lower() not in stages[:-1]:
                _refuse(number, "has a --from that is not an earlier stage "
                        "of this Dockerfile, named with AS")
        if keyword == "add" and ("://" in line
                                 or any(c in line for c in "@$\"'\\")):
            _refuse(number, "is an ADD with a URL, a git source or a $, "
                    "quote or backslash: ADD takes plain local paths only, "
                    "and COPY does the rest")


def _from(number, args, stages):
    """The AS name of the stage a FROM starts ('' when it has none), once
    its base is an earlier stage or an allowed image. A stage is looked up
    folded to lower case, as Docker folds it where AS defines it and where
    FROM names it, so `FROM Build` after `AS Build` is that stage. An image
    is matched as written: Docker refuses an upper-case reference."""
    named = len(args) == 3 and args[1].lower() == "as"
    name = args[2].lower() if named else ""
    if not (len(args) == 1 or (named and _STAGE.fullmatch(name))) or not (
            args[0].lower() in stages or _allowed_base(args[0])):
        _refuse(number, "must be FROM python or python:<tag>, FROM "
                f"{PLATFORM_BASE}:<X.Y.Z>, or FROM an earlier stage of "
                "this Dockerfile, with an optional AS <name>")
    return name


def _allowed_base(image):
    name, colon, tag = image.partition(":")
    if name == PLATFORM_BASE:
        return bool(colon) and bool(_RELEASE.fullmatch(tag))
    return (name in ALLOWED_BASES and (not colon or bool(_TAG.fullmatch(tag)))
            and "onbuild" not in tag)


def _instructions(text):
    """(line number, instruction) for each instruction of *text*, joined as
    moby/buildkit's parser joins them: a line ending in a backslash and
    spaces or tabs continues on the next; inside a continuation, comment
    and blank lines are dropped and do not end it. Refuses a parser
    directive before the first instruction."""
    lines = [line.removesuffix("\r") for line in text.split("\n")]
    index, first = 0, True
    while index < len(lines):
        number, line = index + 1, lines[index].lstrip(" \t")
        index += 1
        if line.startswith("#"):
            if first and _DIRECTIVE.match(line):
                _refuse(number, "is a parser directive (# name=value "
                        "before the first instruction): # syntax= chooses "
                        "the image that builds a Dockerfile and # escape= "
                        "how it is read, so a function Dockerfile has none")
            continue
        line, more = _continued(number, line)
        while more and index < len(lines):
            part = lines[index]
            index += 1
            if not part.strip(" \t") or part.lstrip(" \t").startswith("#"):
                continue
            part, more = _continued(index, part)
            line += part
        if line.strip(" \t"):
            first = False
            yield number, line


def _continued(number, line):
    """*line* without its continuation backslash, and 1 if it had one."""
    if _ESCAPED_END.search(line):
        _refuse(number, "ends in two backslashes, which one version of "
                "Docker's parser reads as continued and another as ended")
    return _CONTINUES.subn("", line)


def _refuse(number, why):
    raise BundleRefused(
        f"Line {number} of the function bundle's Dockerfile {why}.")


def _is_regular(path: Path) -> bool:
    try:
        return stat.S_ISREG(path.lstat().st_mode)
    except OSError:
        return False
